import {test} from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {openStore} from '../server/store.mjs';
import {openObservationInbox,observationHits} from '../server/observation-inbox.mjs';
import {createService} from '../server/service.mjs';
const topic=()=>({id:'t',title:'Synthetic',version:2,status:'active',hypothesis:{reviewAt:'2026-10-01'},claims:[],companies:[{symbol:'TEST.US'}],evidence:[{id:'e',claim:'Counter',stance:'against',verification:'unverified'}]});
const book=()=>({positions:[{symbol:'TEST.US',topicId:'t',openedAt:'2026-09-01T00:00:00Z',researchVersion:1}],reviews:[]});
test('known deadlines, new holding version and counterevidence become separate hits; missing dates and prices do not',()=>{assert.equal(observationHits([topic()],book(),'2026-10-01').length,3);const t=topic();t.hypothesis.reviewAt='2026-02-30';t.evidence=[];assert.equal(observationHits([t],{positions:[],reviews:[]},'2026-10-01').length,0);assert.throws(()=>observationHits([t],book(),'invalid'));});
test('durable hits deduplicate across restart and new evidence survives completion of the old todo',()=>{const dir=mkdtempSync(join(tmpdir(),'signal-observations-')),path=join(dir,'test.sqlite');let s=openStore(path);try{let inbox=openObservationInbox(s,{clock:()=> '2026-10-01T12:00:00Z'});assert.equal(inbox.process([topic()],book()).added,3);assert.equal(inbox.process([topic()],book()).added,0);const item=inbox.snapshot().items.find(i=>i.kind==='counterevidence');inbox.respond(item.id,{revision:1,action:'read',note:'Still investigating'});assert.equal(inbox.snapshot().pending,3);assert.throws(()=>inbox.respond(item.id,{revision:1,action:'complete',note:'Stale'}));inbox.respond(item.id,{revision:2,action:'complete',note:'Reviewed old evidence'});s.close();s=openStore(path);inbox=openObservationInbox(s,{clock:()=> '2026-10-01T12:00:00Z'});assert.equal(inbox.process([topic()],book()).added,0);assert.equal(inbox.receipts(item.id).length,2);const next=topic();next.version=3;next.evidence.push({id:'new',claim:'New risk',stance:'against',verification:'unverified'});inbox.process([next],book());assert(inbox.snapshot().items.some(i=>i.kind==='counterevidence'&&i.topicVersion===3&&i.state==='pending'));assert.equal(inbox.snapshot().items.find(i=>i.id===item.id).state,'completed');}finally{s.close();rmSync(dir,{recursive:true,force:true});}});
test('background tick persists observation checks without GET side effects or paper mutations',async()=>{const s=openStore(':memory:'),service=createService(s,{mode:'demo'});try{const before=JSON.stringify(service.paper.snapshot());service.snapshot();assert.equal(service.observations.snapshot().items.length,0);await service.tick();assert(service.operations().tasks.observations);assert.equal(JSON.stringify(service.paper.snapshot()),before);assert(service.observations.snapshot().items.length>0);}finally{await service.close();s.close();}});
import {openResearch} from '../server/research.mjs';
import {openPaper} from '../server/paper.mjs';
import {latestReview,pendingCounterevidence} from '../shared/review-state.mjs';
test('same topic/evidence reopening or a newly exposed holding creates a fresh todo, ordinary ticks remain idempotent',()=>{const s=openStore(':memory:'),inbox=openObservationInbox(s,{clock:()=> '2026-10-01T12:00:00Z'}),t=topic(),b=book();try{t.hypothesis={};b.positions[0].researchVersion=t.version;b.positions[0].lifecycleId='old-position';assert.equal(inbox.process([t],b).added,1);const old=inbox.snapshot().items[0];inbox.respond(old.id,{revision:1,action:'complete',note:'Old holding only'});assert.equal(inbox.process([t],b).added,0);b.positions[0]={...b.positions[0],lifecycleId:'reopened-position',openedAt:'2026-10-01T11:00:00Z'};assert.equal(inbox.process([t],b).added,1);assert.equal(inbox.process([t],b).added,0);t.companies.push({symbol:'OTHER.US'});b.positions.push({symbol:'OTHER.US',topicId:t.id,openedAt:'2026-10-01T11:10:00Z',researchVersion:t.version,lifecycleId:'new-exposure'});assert.equal(inbox.process([t],b).added,1);const newest=inbox.snapshot().items.find(i=>i.affectedPositions.length===2);assert(newest.affectedPositions.some(p=>p.lifecycleId==='new-exposure'));assert.equal(inbox.snapshot().items.find(i=>i.id===old.id).state,'completed');assert.equal(inbox.process([t],b).added,0);}finally{s.close();}});
test('unchanged legacy holdings keep stable fingerprints without rewriting their history',()=>{const s=openStore(':memory:'),inbox=openObservationInbox(s,{clock:()=> '2026-10-01T12:00:00Z'}),t=topic(),b=book();try{t.hypothesis={};b.positions[0].researchVersion=t.version;inbox.process([t],b);const first=inbox.snapshot().items[0];assert.match(first.affectedPositions[0].lifecycleId,/legacy:/);assert.equal(inbox.process([t],b).added,0);assert.equal(b.positions[0].lifecycleId,undefined);b.positions[0].openedAt='2026-10-01T11:00:00Z';assert.equal(inbox.process([t],b).added,1);}finally{s.close();}});
test('review acknowledgement from a prior lifecycle never suppresses the reopened holding at the same timestamp',()=>{const t=topic(),b=book();b.positions[0].lifecycleId='new';b.reviews=[{symbol:'TEST.US',topicId:'t',positionLifecycleId:'old',at:b.positions[0].openedAt,result:'intact',reviewedResearchVersion:2,reviewedEvidence:[]}];assert.equal(latestReview(b,b.positions[0]),undefined);assert.equal(pendingCounterevidence(t,b,b.positions).length,1);});
test('scenario close and reopen produce distinct lifecycles even at the same clock instant',()=>{const s=openStore(':memory:'),r=openResearch(s),clock=()=> '2026-10-01T12:00:00Z',p=openPaper(s,r,{clock});try{const topicId='memory-global',symbol='MU.US',propose=side=>{const b=p.snapshot();p.propose({version:b.version,clientId:crypto.randomUUID(),topicId,topicVersion:r.get(topicId).version,symbol,side,qty:100,price:120,limit:side==='buy'?125:110,reason:'Synthetic lifecycle',holdingHorizon:'One day',invalidation:'Synthetic risk'});const next=p.snapshot(),o=next.orders.find(o=>o.status==='pending'&&o.symbol===symbol&&o.side===side);p.decide(o.id,{version:next.version,decision:'approve',confirmScenario:true});};propose('buy');const first=p.snapshot().positions.find(x=>x.symbol===symbol);assert(first.lifecycleId);p.review({version:p.snapshot().version,topicVersion:r.get(topicId).version,symbol,result:'intact',note:'Synthetic old lifecycle'});assert.equal(latestReview(p.snapshot(),first).positionLifecycleId,first.lifecycleId);propose('sell');assert(!p.snapshot().positions.some(x=>x.symbol===symbol));propose('buy');const next=p.snapshot().positions.find(x=>x.symbol===symbol);assert.equal(first.openedAt,next.openedAt);assert.notEqual(first.lifecycleId,next.lifecycleId);assert.equal(latestReview(p.snapshot(),next),undefined);}finally{s.close();}});
